    public static LayerDefinition layer(String id) {
        return switch (id) {
            case "kozue" -> bodyKozue();
            case "homura" -> bodyHomura();
            case "kura" -> bodyKura();
            case "shiori" -> bodyShiori();
            case "oveja" -> bodyOveja();
            case "vaca" -> bodyVaca();
            case "cerdo" -> bodyCerdo();
            case "gallina" -> bodyGallina();
            case "perro" -> bodyPerro();
            case "gato" -> bodyGato();
            case "golem" -> bodyGolem();
            case "aldeana" -> bodyAldeana();
            case "zombie" -> bodyZombie();
            case "esqueleto" -> bodyEsqueleto();
            case "creeper" -> bodyCreeper();
            case "arana" -> bodyArana();
            case "bruja" -> bodyBruja();
            case "enderman" -> bodyEnderman();
            default -> bodyKozue();
        };
    }

    public static Map<String, ModelPart> bake(String id, ModelPart root) {
        return switch (id) {
            case "kozue" -> bakeBodyKozue(root);
            case "homura" -> bakeBodyHomura(root);
            case "kura" -> bakeBodyKura(root);
            case "shiori" -> bakeBodyShiori(root);
            case "oveja" -> bakeBodyOveja(root);
            case "vaca" -> bakeBodyVaca(root);
            case "cerdo" -> bakeBodyCerdo(root);
            case "gallina" -> bakeBodyGallina(root);
            case "perro" -> bakeBodyPerro(root);
            case "gato" -> bakeBodyGato(root);
            case "golem" -> bakeBodyGolem(root);
            case "aldeana" -> bakeBodyAldeana(root);
            case "zombie" -> bakeBodyZombie(root);
            case "esqueleto" -> bakeBodyEsqueleto(root);
            case "creeper" -> bakeBodyCreeper(root);
            case "arana" -> bakeBodyArana(root);
            case "bruja" -> bakeBodyBruja(root);
            case "enderman" -> bakeBodyEnderman(root);
            default -> bakeBodyKozue(root);
        };
    }

